from __future__ import annotations

from pathlib import Path


def once(text: str, old: str, new: str, label: str) -> str:
    if old not in text:
        raise RuntimeError(f"backend completion anchor missing: {label}")
    return text.replace(old, new, 1)


def patch_returns() -> None:
    p=Path('jewel_server/returns.py');t=p.read_text(encoding='utf-8')
    anchor='''\ndef post_sale_return(conn, sale_id: int, payload: dict[str, Any], user: dict[str, Any], client_ip: str | None = None) -> dict[str, Any]:\n'''
    quote='''\ndef quote_sale_return(conn, sale_id: int, sale_item_ids: list[int] | None = None) -> dict[str, Any]:\n    sale_row=conn.execute("SELECT * FROM sales WHERE id=?",(sale_id,)).fetchone()\n    if not sale_row:raise HTTPException(404,"Sale not found")\n    sale=dict(sale_row)\n    if sale["status"]!="posted":raise HTTPException(409,"Cancelled invoices cannot be returned")\n    requested=[] if sale_item_ids is None else [int(x) for x in sale_item_ids]\n    if len(requested)!=len(set(requested)):raise HTTPException(400,"Select unique invoice items")\n    all_lines=conn.execute("SELECT si.*,i.status item_status FROM sale_items si JOIN items i ON i.id=si.item_id WHERE si.sale_id=? ORDER BY si.id",(sale_id,)).fetchall()\n    line_ids={int(x["id"]) for x in all_lines}\n    if any(i not in line_ids for i in requested):raise HTTPException(400,"A selected item does not belong to this invoice")\n    active={int(x[0]) for x in conn.execute("SELECT ri.sale_item_id FROM sale_return_items ri JOIN sale_returns r ON r.id=ri.return_id WHERE r.status='posted' AND ri.active=1 AND ri.sale_item_id IN (SELECT id FROM sale_items WHERE sale_id=?)",(sale_id,)).fetchall()}\n    allocations=_round_off_allocations(conn,sale_id);selected=set(requested);lines=[];taxable=gst=round_off=total=cost=0\n    for raw in all_lines:\n        line=dict(raw);line_id=int(line["id"]);already=line_id in active;returnable=(not already and line["item_status"]=="sold")\n        ro=int(allocations.get(line_id,0));line_total=int(line["line_total_paise"] or 0)+ro\n        if line_id in selected and not returnable:raise HTTPException(409,f"Tag {line['tag_no']} is not currently returnable")\n        entry={"sale_item_id":line_id,"item_id":line["item_id"],"tag_no":line["tag_no"],"description":line["description"],"metal":line["metal"],"purity":line["purity"],"item_status":line["item_status"],"already_returned":already,"returnable":returnable,"selected":line_id in selected,"taxable":_rupees(int(line["taxable_paise"] or 0)),"gst":_rupees(int(line["gst_amount_paise"] or 0)),"round_off":_rupees(ro),"total":_rupees(line_total),"cost":_rupees(int(line["cost_amount_paise"] or 0))}\n        lines.append(entry)\n        if line_id in selected:\n            taxable+=int(line["taxable_paise"] or 0);gst+=int(line["gst_amount_paise"] or 0);round_off+=ro;total+=line_total;cost+=int(line["cost_amount_paise"] or 0)\n    cgst,sgst,igst=_split_return_gst(sale,gst)\n    customer=None\n    if sale.get("customer_id"):\n        row=conn.execute("SELECT id,code,name,phone,gstin,balance,balance_paise FROM customers WHERE id=?",(sale["customer_id"],)).fetchone();customer=dict(row) if row else None\n    return {"sale":{"id":sale["id"],"invoice_no":sale["invoice_no"],"business_date":sale.get("business_date"),"customer_id":sale.get("customer_id"),"total":_rupees(int(sale["total_paise"] or 0))},"customer":customer,"lines":lines,"selected_count":len(selected),"taxable":_rupees(taxable),"gst":_rupees(gst),"cgst":_rupees(cgst),"sgst":_rupees(sgst),"igst":_rupees(igst),"round_off":_rupees(round_off),"total":_rupees(total),"cost":_rupees(cost)}\n\n'''
    t=once(t,anchor,quote+anchor,'return quote function')
    p.write_text(t,encoding='utf-8')


def patch_services() -> None:
    p=Path('jewel_server/services.py');t=p.read_text(encoding='utf-8')
    t=once(t,'from .precision import decimal_value,money,money_decimal,money_equal,money_paise,money_sum,nearest_rupee,weight,weight_decimal,weight_equal,weight_mg','from .precision import decimal_value,money,money_decimal,money_equal,money_paise,money_sum,nearest_rupee,paise_money,weight,weight_decimal,weight_equal,weight_mg','precision paise helper')
    t=t.replace("(money(newp/100),newp,now,cid)","(paise_money(newp),newp,now,cid)")
    t=t.replace("(money(newp/100),newp,now,sale['customer_id'])","(paise_money(newp),newp,now,sale['customer_id'])")
    p.write_text(t,encoding='utf-8')


def patch_db() -> None:
    p=Path('jewel_server/db.py');t=p.read_text(encoding='utf-8')
    t=t.replace("VALUES('MAIN','Main Showroom','','','',1)","VALUES('MAIN','Bijoria Main Showroom','','','',1)")
    p.write_text(t,encoding='utf-8')


